    <script>
        const slides = document.querySelectorAll('.slide');
        const totalSlides = slides.length;
        let currentSlide = 1;

        const slideTitles = [
            "1. Cover & Judul Kebijakan",
            "2. Latar Belakang & Tahapan Transformasi",
            "3. Maksud & Tujuan Strategis",
            "4. 9 Prinsip Dasar Pemerintah Digital",
            "5. Keterkaitan Antar Domain SPBE",
            "6. Domain 1: Proses Bisnis",
            "7. Domain 2: Data & Informasi",
            "8. Domain 3: Layanan Digital 24/7",
            "9. Domain 4: GovTech & Aplikasi SPBE",
            "10. Domain 5: Infrastruktur TIK & JIP",
            "11. Domain 6: Keamanan Siber & TTE",
            "12. Matriks Bukti Dukung (Evidence)",
            "13. Tiga Langkah Formulasi Peta Jalan",
            "14. Peta Kondisi Eksisting & Gap Arsitektur",
            "15. Modal Awal & Baseline Data Daerah 2026",
            "16. Domain 1 & 3: Probis & Layanan Digital",
            "17. Domain 2, 4, & 6: Aplikasi, Data, & Siber",
            "18. Matriks Evaluasi Kesiapan Data 6 Domain",
            "19. Display Infografis Evaluasi SPBE",
            "20. Penutup & Kontak Mitra"
        ];

        function updatePresentation() {
            // Show/Hide slide elements
            slides.forEach((slide) => {
                const slideIndex = parseInt(slide.getAttribute('data-slide'));
                if (slideIndex === currentSlide) {
                    slide.classList.remove('hidden');
                } else {
                    slide.classList.add('hidden');
                }
            });

            // Update counter text
            document.getElementById('slideCounter').innerText = `Slide ${currentSlide} / ${totalSlides}`;

            // Update button states
            document.getElementById('prevBtn').disabled = currentSlide === 1;
            const nextBtn = document.getElementById('nextBtn');
            if (currentSlide === totalSlides) {
                nextBtn.innerHTML = `Selesai <span class="material-symbols-outlined text-sm ml-1">check</span>`;
            } else {
                nextBtn.innerHTML = `Berikutnya <span class="material-symbols-outlined text-sm ml-1">arrow_forward</span>`;
            }

            // Update dots
            updateDots();
        }

        function goToSlide(n) {
            if (n >= 1 && n <= totalSlides) {
                currentSlide = n;
                updatePresentation();
            }
        }

        function nextSlide() {
            if (currentSlide < totalSlides) {
                currentSlide++;
                updatePresentation();
            }
        }

        function prevSlide() {
            if (currentSlide > 1) {
                currentSlide--;
                updatePresentation();
            }
        }

        // Initialize Navigation Dots
        function initDots() {
            const container = document.getElementById('slideDots');
            container.innerHTML = '';
            for (let i = 1; i <= totalSlides; i++) {
                const dot = document.createElement('button');
                dot.className = `w-2.5 h-2.5 rounded-full transition-all duration-300 ${i === currentSlide ? 'bg-emerald-700 w-6' : 'bg-slate-300 hover:bg-slate-400'}`;
                dot.title = slideTitles[i - 1];
                dot.onclick = () => goToSlide(i);
                container.appendChild(dot);
            }
        }

        function updateDots() {
            const container = document.getElementById('slideDots');
            const dots = container.querySelectorAll('button');
            dots.forEach((dot, idx) => {
                if (idx + 1 === currentSlide) {
                    dot.className = 'w-6 h-2.5 rounded-full bg-emerald-700 transition-all duration-300';
                } else {
                    dot.className = 'w-2.5 h-2.5 rounded-full bg-slate-300 hover:bg-slate-400 transition-all duration-300';
                }
            });
        }

        // Modal Grid Overview Generation
        function initGridModal() {
            const container = document.getElementById('gridCardsContainer');
            container.innerHTML = '';
            slideTitles.forEach((title, idx) => {
                const card = document.createElement('div');
                const num = idx + 1;
                card.className = `p-4 rounded-xl cursor-pointer border transition text-left ${num === currentSlide ? 'bg-emerald-800 text-white border-amber-400 ring-2 ring-amber-400' : 'bg-slate-800 text-slate-200 border-slate-700 hover:bg-slate-700'}`;
                card.innerHTML = `
          <div class="text-[11px] font-bold text-amber-300 mb-1">SLIDE ${num}</div>
          <div class="text-sm font-semibold leading-tight">${title}</div>
        `;
                card.onclick = () => {
                    goToSlide(num);
                    toggleGridModal();
                };
                container.appendChild(card);
            });
        }

        function toggleGridModal() {
            const modal = document.getElementById('gridModal');
            if (modal.classList.contains('hidden')) {
                initGridModal();
                modal.classList.remove('hidden');
            } else {
                modal.classList.add('hidden');
            }
        }


        // Toggle Gap Image Zoom Modal
        function toggleGapImageModal() {
            const modal = document.getElementById('gapImageModal');
            if (modal) {
                modal.classList.toggle('hidden');
            }
        }

        // Fullscreen Toggle
        function toggleFullscreen() {
            const elem = document.documentElement;
            const fsIcon = document.getElementById('fsIcon');
            if (!document.fullscreenElement) {
                if (elem.requestFullscreen) {
                    elem.requestFullscreen();
                    fsIcon.innerText = 'fullscreen_exit';
                }
            } else {
                if (document.exitFullscreen) {
                    document.exitFullscreen();
                    fsIcon.innerText = 'fullscreen';
                }
            }
        }

