        // Open Modal for Any Domain (1 to 6)
        function openDomainModal(domainNum = 1, point = 'all', mode = 'pertanyaan') {
            currentDomainNum = domainNum;
            currentDomainPoint = point;
            currentDomainMode = mode;

            const modal = document.getElementById('domain1Modal');
            if (modal) {
                modal.classList.remove('hidden');
            }

            updateDomainHeaderUI();
            updateDomainTabsUI();
            updateDomainModeUI();
            renderDomainContent();
        }

        // Close Modal
        function closeDomainModal() {
            const modal = document.getElementById('domain1Modal');
            if (modal) {
                modal.classList.add('hidden');
            }
        }

        // Filter Point
        function filterDomainModal(point) {
            currentDomainPoint = point;
            updateDomainTabsUI();
            renderDomainContent();
        }

        // Set View Mode (pertanyaan vs tabel)
        function setDomainMode(mode) {
            currentDomainMode = mode;
            updateDomainModeUI();
            renderDomainContent();
        }

        // Update Header Box UI (Badge, Icon, Color Theme)
        function updateDomainHeaderUI() {
            const cfg = domainConfigs[currentDomainNum] || domainConfigs[1];

            // Update icon & badge
            const iconElem = document.getElementById('domainModalIcon');
            const iconWrapper = document.getElementById('domainModalIconWrapper');
            const badgeElem = document.getElementById('domainModalBadge');

            if (iconElem) iconElem.innerText = cfg.icon;
            if (iconWrapper) {
                iconWrapper.className = `w-8 h-8 rounded-lg ${cfg.iconBg} border ${cfg.iconBorder} ${cfg.iconText} flex items-center justify-center shrink-0 shadow-2xs mt-0.5`;
            }
            if (badgeElem) {
                badgeElem.className = `px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${cfg.badgeBg} ${cfg.badgeText} border ${cfg.badgeBorder}`;
                badgeElem.innerText = cfg.badge;
            }
        }

        // Update Point Tabs UI
        function updateDomainTabsUI() {
            const cfg = domainConfigs[currentDomainNum] || domainConfigs[1];
            const tabsContainer = document.getElementById('domain1PointTabs');
            if (!tabsContainer) return;

            const pointsKeys = Object.keys(cfg.points); // ['all', 'p1', 'p2', ...]

            let tabsHtml = '';
            pointsKeys.forEach(ptKey => {
                const pt = cfg.points[ptKey];
                const isActive = (ptKey === currentDomainPoint);

                if (ptKey === 'all') {
                    tabsHtml += `
            <button onclick="filterDomainModal('all')" id="tab_dm_all"
              class="domain-tab-btn px-2.5 py-1 rounded-lg text-[11px] font-bold transition flex items-center gap-1 ${isActive
                            ? cfg.btnActive
                            : 'bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 shadow-2xs'
                        }">
              <span class="material-symbols-outlined text-xs">select_all</span>
              <span>Semua 10 Soal</span>
            </button>
          `;
                } else {
                    const ptNum = ptKey.replace('p', '');
                    tabsHtml += `
            <button onclick="filterDomainModal('${ptKey}')" id="tab_dm_${ptKey}"
              class="domain-tab-btn px-2.5 py-1 rounded-lg text-[11px] font-medium transition flex items-center gap-1.5 ${isActive
                            ? cfg.btnActive
                            : 'bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 shadow-2xs'
                        }">
              <span class="w-3.5 h-3.5 rounded-full ${isActive ? 'bg-white/20 text-white' : 'bg-slate-200 text-slate-800'} flex items-center justify-center text-[9px] font-bold">${ptNum}</span>
              <span>${pt.tabLabel || ('Poin ' + ptNum)}</span>
              <span class="text-[10px] ${isActive ? 'text-white/80' : 'text-slate-400'} font-normal">${pt.tabSub || ''}</span>
            </button>
          `;
                }
            });

            tabsContainer.innerHTML = tabsHtml;

            // Update Modal Title
            const currentPointInfo = cfg.points[currentDomainPoint] || cfg.points.all;
            const titleElem = document.getElementById('domain1ModalTitle');
            if (titleElem) {
                titleElem.innerText = currentDomainMode === 'pertanyaan'
                    ? `Kuesioner: ${currentPointInfo.title}`
                    : `Tabel Bukti Dukung: ${currentPointInfo.title}`;
            }
        }

        // Update Mode Switcher UI
        function updateDomainModeUI() {
            const cfg = domainConfigs[currentDomainNum] || domainConfigs[1];
            const btnPertanyaan = document.getElementById('btnD1ModePertanyaan');
            const btnTabel = document.getElementById('btnD1ModeTabel');
            const qContainer = document.getElementById('domain1QuestionsContainer');
            const tContainer = document.getElementById('domain1TableContainer');

            if (currentDomainMode === 'pertanyaan') {
                if (btnPertanyaan) btnPertanyaan.className = `px-2.5 py-1 rounded-md text-[11px] font-bold transition flex items-center gap-1 ${cfg.btnActive}`;
                if (btnTabel) btnTabel.className = 'px-2.5 py-1 rounded-md text-[11px] font-medium transition flex items-center gap-1 text-slate-600 hover:text-slate-900 hover:bg-slate-200 bg-transparent';
                if (qContainer) qContainer.classList.remove('hidden');
                if (tContainer) tContainer.classList.add('hidden');
            } else {
                if (btnTabel) btnTabel.className = `px-2.5 py-1 rounded-md text-[11px] font-bold transition flex items-center gap-1 ${cfg.btnActive}`;
                if (btnPertanyaan) btnPertanyaan.className = 'px-2.5 py-1 rounded-md text-[11px] font-medium transition flex items-center gap-1 text-slate-600 hover:text-slate-900 hover:bg-slate-200 bg-transparent';
                if (tContainer) tContainer.classList.remove('hidden');
                if (qContainer) qContainer.classList.add('hidden');
            }

            // Update Modal Title
            const currentPointInfo = cfg.points[currentDomainPoint] || cfg.points.all;
            const titleElem = document.getElementById('domain1ModalTitle');
            if (titleElem) {
                titleElem.innerText = currentDomainMode === 'pertanyaan'
                    ? `Kuesioner: ${currentPointInfo.title}`
                    : `Tabel Bukti Dukung: ${currentPointInfo.title}`;
            }
        }

        // Render Content (Questions or Table)
        function renderDomainContent() {
            const cfg = domainConfigs[currentDomainNum] || domainConfigs[1];
            const currentPointInfo = cfg.points[currentDomainPoint] || cfg.points.all;
            const questionsList = domainQuestionsData[currentDomainNum] || [];
            const evidenceRows = domainEvidenceTableData[currentDomainNum] || [];

            // 1. Render Questions View (LIGHT THEME)
            const qContainer = document.getElementById('domain1QuestionsContainer');
            if (qContainer) {
                const filteredQuestions = questionsList.filter(q => {
                    if (currentDomainPoint === 'all') return true;
                    return q.point === currentDomainPoint;
                });

                let qHtml = `
          <!-- Header Banner Point (Light Theme) -->
          <div class="p-3.5 sm:p-4 rounded-xl ${cfg.badgeBg} border ${cfg.badgeBorder} flex items-start gap-3 shadow-xs">
            <div class="w-8 h-8 rounded-lg bg-white/80 ${cfg.badgeText} flex items-center justify-center shrink-0 text-base font-bold border ${cfg.badgeBorder}">
              <span class="material-symbols-outlined text-lg">${cfg.icon}</span>
            </div>
            <div class="flex-1 text-xs">
              <div class="font-extrabold text-slate-900 text-sm sm:text-base">${currentPointInfo.title}</div>
              <p class="text-slate-700 mt-0.5 leading-relaxed">${currentPointInfo.sub}</p>
              <div class="mt-2 flex flex-wrap items-center gap-1.5">
                <span class="text-[11px] text-slate-600 font-semibold">Menampilkan <strong>${filteredQuestions.length}</strong> butir pertanyaan kuesioner:</span>
                ${currentPointInfo.qIds.map(num => `<span class="px-2 py-0.5 rounded bg-white ${cfg.badgeText} border ${cfg.badgeBorder} font-mono font-bold text-[10px] shadow-2xs">Soal #${num}</span>`).join('')}
              </div>
            </div>
          </div>
        `;

                filteredQuestions.forEach((qItem) => {
                    qHtml += `
            <div class="p-4 sm:p-5 rounded-xl bg-white border border-slate-200/90 shadow-sm hover:border-slate-300 hover:shadow-md transition space-y-3">
              <!-- Question Header -->
              <div class="flex items-start justify-between gap-3">
                <div class="flex items-start gap-2.5">
                  <span class="px-2.5 py-1 rounded-lg ${cfg.badgeBg} ${cfg.badgeText} border ${cfg.badgeBorder} font-bold text-xs shrink-0 font-mono">
                    Soal #${qItem.id}
                  </span>
                  <div>
                    <span class="text-[10px] uppercase font-bold tracking-wider ${cfg.badgeText} block mb-0.5">
                      ${qItem.pointBadge}
                    </span>
                    <h4 class="text-sm sm:text-base font-bold text-slate-900 leading-snug">
                      ${qItem.question}
                    </h4>
                  </div>
                </div>
                <span class="text-[11px] text-slate-500 shrink-0 hidden sm:inline-block bg-slate-100 px-2 py-0.5 rounded border border-slate-200 font-medium">Pilihan Ganda</span>
              </div>

              <!-- Options List (5 Levels) -->
              <div class="space-y-2 pt-1">
                ${qItem.options.map((opt) => {
                        const isTopLevel = opt.level >= 4;
                        return `
                    <label class="group flex items-start gap-3 p-2.5 sm:p-3 rounded-lg border transition cursor-pointer ${isTopLevel
                                ? 'bg-slate-50/70 hover:bg-slate-100/80 border-slate-200 hover:border-slate-300'
                                : 'bg-white hover:bg-slate-50 border-slate-200/90 hover:border-slate-300'
                            }">
                      <div class="flex items-center h-5 mt-0.5">
                        <input type="radio" name="d${currentDomainNum}_question_${qItem.id}" value="${opt.level}" 
                          class="w-4 h-4 text-slate-800 bg-white border-slate-300 focus:ring-slate-500 focus:ring-2">
                      </div>
                      <div class="flex-1 min-w-0 text-xs">
                        <div class="flex items-center gap-2 mb-0.5">
                          <span class="px-1.5 py-0.5 rounded text-[10px] font-mono font-bold ${opt.level === 5 ? 'bg-emerald-200 text-emerald-950 border border-emerald-300 font-bold ring-1 ring-emerald-300' :
                                opt.level === 4 ? 'bg-teal-100 text-teal-900 border border-teal-300' :
                                    opt.level === 3 ? 'bg-amber-100 text-amber-900 border border-amber-300' :
                                        'bg-slate-200 text-slate-800'
                            }">Level ${opt.level}</span>
                          <span class="text-[11px] font-bold text-slate-800">${opt.title}</span>
                        </div>
                        <p class="text-slate-600 group-hover:text-slate-900 leading-relaxed text-xs">
                          ${opt.text}
                        </p>
                      </div>
                    </label>
                  `;
                    }).join('')}
              </div>
            </div>
          `;
                });

                qContainer.innerHTML = qHtml;
            }

            // 2. Render Evidence Table View (LIGHT THEME)
            const tContainer = document.getElementById('domain1TableContainer');
            if (tContainer) {
                const filteredRows = evidenceRows.filter(row => {
                    if (currentDomainPoint === 'all') return true;
                    return row.point === currentDomainPoint;
                });

                let tHtml = `
          <!-- Header Banner Evidence Table (Light Theme) -->
          <div class="p-3.5 sm:p-4 rounded-xl ${cfg.badgeBg} border ${cfg.badgeBorder} flex items-start justify-between gap-3 flex-wrap shadow-xs">
            <div class="flex items-start gap-3">
              <div class="w-8 h-8 rounded-lg bg-white/80 ${cfg.badgeText} flex items-center justify-center shrink-0 border ${cfg.badgeBorder}">
                <span class="material-symbols-outlined text-lg">table_view</span>
              </div>
              <div class="text-xs">
                <div class="font-extrabold text-slate-900 text-sm sm:text-base">${cfg.evidenceTitle}</div>
                <p class="text-slate-700 mt-0.5 leading-relaxed">${currentPointInfo.evidenceGuide || cfg.points.all.evidenceGuide}</p>
              </div>
            </div>
            <div class="flex items-center gap-2">
              <span class="px-2.5 py-1 rounded bg-amber-100 text-amber-900 border border-amber-300 text-[11px] font-bold">
                ${cfg.evidenceExampleBadge}
              </span>
            </div>
          </div>

          <!-- Official Table Container (Light Theme) -->
          <div class="overflow-x-auto rounded-xl border border-slate-200 bg-white shadow-sm">
            <table class="w-full text-left text-xs border-collapse">
              <thead>
                <tr class="bg-slate-100 border-b border-slate-200 text-slate-800 font-bold">
                  ${cfg.tableCols.map((col, idx) => `
                    <th class="p-3 font-bold ${col.width || ''} ${idx < cfg.tableCols.length - 1 ? 'border-r border-slate-200' : ''}">${col.label}</th>
                  `).join('')}
                </tr>
              </thead>
              <tbody class="divide-y divide-slate-200 text-slate-700">
                ${filteredRows.map((row, rIdx) => `
                  <tr class="hover:bg-slate-50 transition ${row.isExample ? 'bg-amber-50/60' : ''}">
                    <td class="p-3 text-center font-mono font-bold text-slate-500 border-r border-slate-200">${rIdx + 1}</td>
                    <td class="p-3 font-medium text-slate-900 border-r border-slate-200">
                      <div class="flex flex-col">
                        <span class="font-bold text-slate-900">${row.cells[0]}</span>
                        <div class="flex items-center gap-1.5 mt-1">
                          <span class="text-[10px] px-1.5 py-0.2 rounded ${cfg.badgeBg} ${cfg.badgeText} border ${cfg.badgeBorder} font-semibold">${row.pointBadge}</span>
                          ${row.isExample ? '<span class="text-[10px] px-1.5 py-0.2 rounded bg-amber-100 text-amber-800 border border-amber-200 font-semibold italic">Format Contoh Resmi</span>' : ''}
                        </div>
                      </div>
                    </td>
                    ${row.cells.slice(1).map((cellText, cIdx) => {
                    const isLast = (cIdx === row.cells.length - 2);
                    const isStatusCol = (cIdx === 1 && (cellText === 'Ada' || cellText === 'Sudah Diterapkan'));
                    return `
                        <td class="p-3 ${isLast ? '' : 'border-r border-slate-200'}">
                          ${isStatusCol ? `
                            <span class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800 border border-emerald-300">
                              <span class="w-1.5 h-1.5 rounded-full bg-emerald-600"></span>
                              ${cellText}
                            </span>
                          ` : cellText}
                        </td>
                      `;
                }).join('')}
                  </tr>
                `).join('')}

                <!-- Template Baris Kosong untuk Praktik Isian OPD -->
                <tr class="bg-slate-50/50 text-slate-500 italic">
                  <td class="p-3 text-center font-mono border-r border-slate-200">${filteredRows.length + 1}</td>
                  <td class="p-3 border-r border-slate-200"><em>[Isi Data Bukti Sesuai Penugasan OPD Saudara]</em></td>
                  ${cfg.tableCols.slice(2).map((col, idx) => `
                    <td class="p-3 ${idx < cfg.tableCols.length - 3 ? 'border-r border-slate-200' : ''}"><em>[Sesuai Dokumen OPD]</em></td>
                  `).join('')}
                </tr>
              </tbody>
            </table>
          </div>

          <!-- Petunjuk Teknis Pengunggahan Evidence (Light Theme) -->
          <div class="p-3.5 sm:p-4 rounded-xl bg-slate-50 border border-slate-200 space-y-2 text-xs">
            <h5 class="font-bold text-slate-900 flex items-center gap-1.5">
              <span class="material-symbols-outlined text-sm text-slate-700">task_alt</span>
              <span>Ketentuan Verifikasi Bukti Dukung (Evidence Checklist):</span>
            </h5>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-2 text-slate-700">
              ${cfg.checklist.map(item => `
                <div class="p-2.5 rounded-lg bg-white border border-slate-200 shadow-2xs">
                  <p class="font-bold text-slate-900">${item.title}</p>
                  <p class="text-[11px] mt-0.5 leading-relaxed text-slate-600">${item.text}</p>
                </div>
              `).join('')}
            </div>
          </div>
        `;

                tContainer.innerHTML = tHtml;
            }
        }

        // Backwards Compatibility Aliases for Domain 1
        function openDomain1Modal(point = 'all', mode = 'pertanyaan') {
            openDomainModal(1, point, mode);
        }
        function closeDomain1Modal() {
            closeDomainModal();
        }
        function filterDomain1Modal(point) {
            filterDomainModal(point);
        }
        function setDomain1Mode(mode) {
            setDomainMode(mode);
        }

        // Keyboard navigation
        window.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                nextSlide();
            } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
                prevSlide();
            } else if (e.key === 'Escape') {
                const modal = document.getElementById('gridModal');
                if (modal && !modal.classList.contains('hidden')) {
                    modal.classList.add('hidden');
                }
                const gapModal = document.getElementById('gapImageModal');
                if (gapModal && !gapModal.classList.contains('hidden')) {
                    gapModal.classList.add('hidden');
                }
                closeDomainModal();
            }
        });

        // Sinkronkan ikon saat keluar fullscreen via Esc
        document.addEventListener('fullscreenchange', () => {
            document.getElementById('fsIcon').innerText = document.fullscreenElement ? 'fullscreen_exit' : 'fullscreen';
        });

        // Run setup on load

        // Tab switcher for Slide 6 (Domain 1: Probis)
        function switchProbisTab(tab) {
            const v1 = document.getElementById('view-probis-1');
            const v2 = document.getElementById('view-probis-2');
            const b1 = document.getElementById('tab-btn-probis-1');
            const b2 = document.getElementById('tab-btn-probis-2');
            if (!v1 || !v2 || !b1 || !b2) return;
            if (tab === 1) {
                v1.classList.remove('hidden');
                v2.classList.add('hidden');
                b1.className = 'px-2 py-0.5 rounded font-semibold text-white bg-emerald-700 transition';
                b2.className = 'px-2 py-0.5 rounded font-semibold text-slate-400 hover:text-white transition';
            } else {
                v1.classList.add('hidden');
                v2.classList.remove('hidden');
                b2.className = 'px-2 py-0.5 rounded font-semibold text-white bg-emerald-700 transition';
                b1.className = 'px-2 py-0.5 rounded font-semibold text-slate-400 hover:text-white transition';
            }
        }

        // Tab switcher for Slide 7 (Domain 2: Data & Informasi)
        function switchDataTab(tab) {
            const v1 = document.getElementById('view-data-1');
            const v2 = document.getElementById('view-data-2');
            const b1 = document.getElementById('tab-btn-data-1');
            const b2 = document.getElementById('tab-btn-data-2');
            if (!v1 || !v2 || !b1 || !b2) return;
            if (tab === 1) {
                v1.classList.remove('hidden');
                v2.classList.add('hidden');
                b1.className = 'px-2 py-0.5 rounded font-semibold text-white bg-blue-700 transition';
                b2.className = 'px-2 py-0.5 rounded font-semibold text-slate-400 hover:text-white transition';
            } else {
                v1.classList.add('hidden');
                v2.classList.remove('hidden');
                b2.className = 'px-2 py-0.5 rounded font-semibold text-white bg-blue-700 transition';
                b1.className = 'px-2 py-0.5 rounded font-semibold text-slate-400 hover:text-white transition';
            }

            // Tab switcher for Slide 8 (Domain 3: Layanan Digital)
            function switchLayananTab(tab) {
                const v1 = document.getElementById('view-layanan-1');
                const v2 = document.getElementById('view-layanan-2');
                const b1 = document.getElementById('tab-btn-layanan-1');
                const b2 = document.getElementById('tab-btn-layanan-2');
                if (!v1 || !v2 || !b1 || !b2) return;
                if (tab === 1) {
                    v1.classList.remove('hidden');
                    v2.classList.add('hidden');
                    b1.className = 'px-2 py-0.5 rounded font-semibold text-white bg-amber-700 transition';
                    b2.className = 'px-2 py-0.5 rounded font-semibold text-slate-400 hover:text-white transition';
                } else {
                    v1.classList.add('hidden');
                    v2.classList.remove('hidden');
                    b2.className = 'px-2 py-0.5 rounded font-semibold text-white bg-amber-700 transition';
                    b1.className = 'px-2 py-0.5 rounded font-semibold text-slate-400 hover:text-white transition';
                }
            }

        }

        initDots();
        updatePresentation();
    </script>
</body>

</html>